<script setup>
import { computed, nextTick, onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';

import { apiClient, authSession } from '../lib/auth/index.js';

const emptyWorkspace = () => ({ accessReviewCampaignRuns: [], accessReviewCampaigns: [], accessReviewItems: [], accessReviews: [], breakGlassPolicy: null, credentials: [], domains: [], groupMemberships: [], groups: [], impersonationGrants: [], policy: null, roles: [], serviceAccounts: [] });
const router = useRouter();
const workspace = ref(emptyWorkspace()); const loading = ref(true); const errorMessage = ref(''); const activeTab = ref('policy'); const token = computed(() => authSession.state.token); const dialog = ref(null); const editor = reactive({ kind: '', values: {} }); const oneTimeSecret = ref(''); const oneTimeDomainProof = ref('');
const groupMap = computed(() => new Map(workspace.value.groups.map((item) => [item.id, item]))); const accountMap = computed(() => new Map(workspace.value.serviceAccounts.map((item) => [item.id, item])));
async function load() { loading.value = true; errorMessage.value = ''; try { workspace.value = await apiClient.getIdentityWorkspace({ limit: 100 }, token.value); } catch (error) { errorMessage.value = error.message ?? 'Unable to load identity controls.'; } finally { loading.value = false; } }
function blank(kind) {
  if (kind === 'policy') return { audience: workspace.value.policy?.provider?.audience ?? '', clientId: workspace.value.policy?.provider?.clientId ?? '', decryptionKeyReference: workspace.value.policy?.provider?.decryptionKeyReference ?? '', defaultRoleKey: workspace.value.policy?.defaultRoleKey ?? 'user', emailAttribute: workspace.value.policy?.provider?.emailAttribute ?? 'email', entryPoint: workspace.value.policy?.provider?.entryPoint ?? '', expectedVersion: workspace.value.policy?.version ?? 0, groupsAttribute: workspace.value.policy?.provider?.groupsAttribute ?? 'groups', idpCertificate: workspace.value.policy?.provider?.idpCertificate ?? '', issuer: workspace.value.policy?.provider?.issuer ?? '', jitEnabled: workspace.value.policy?.jitEnabled ?? false, loginEnforcement: workspace.value.policy?.loginEnforcement ?? 'optional', metadataUrl: workspace.value.policy?.provider?.metadataUrl ?? '', secretReference: workspace.value.policy?.provider?.secretReference ?? '', spSigningCertReference: workspace.value.policy?.provider?.spSigningCertReference ?? '', spSigningKeyReference: workspace.value.policy?.provider?.spSigningKeyReference ?? '', ssoMode: workspace.value.policy?.ssoMode ?? 'none' };
  if (kind === 'break-glass') return { enabled: workspace.value.breakGlassPolicy?.enabled ?? false, expectedVersion: workspace.value.breakGlassPolicy?.version ?? 0, maxSessionMinutes: workspace.value.breakGlassPolicy?.maxSessionMinutes ?? 15, userIdsText: workspace.value.breakGlassPolicy?.userIds?.join(',') ?? '' };
  if (kind === 'domain') return { domain: '', verificationMethod: 'manual' };
  if (kind === 'role') return { capabilitiesText: 'projects.read', description: '', key: '', name: '' };
  if (kind === 'group') return { description: '', externalId: '', name: '', roleKeysText: 'user' };
  if (kind === 'service') return { description: '', expiresAt: '', name: '', projectIdsText: '', scopesText: 'reporting.read' };
  if (kind === 'review') return { dueAt: new Date(Date.now() + 30 * 86_400_000).toISOString().slice(0, 16), name: '', reviewerUserId: '', scope: 'tenant' };
  if (kind === 'review campaign') return { durationDays: 14, enabled: true, intervalDays: 90, name: '', nextRunAt: new Date(Date.now() + 86_400_000).toISOString().slice(0, 16), reviewerUserId: '', scope: 'tenant' };
  if (kind === 'verify-domain') return { domainId: '', expectedVersion: 0, proof: '' };
  return { expiresAt: new Date(Date.now() + 60 * 60_000).toISOString().slice(0, 16), reason: '', targetUserId: '' };
}
async function openEditor(kind) { editor.kind = kind; editor.values = blank(kind); oneTimeSecret.value = ''; oneTimeDomainProof.value = ''; await nextTick(); dialog.value?.showModal(); }
function closeEditor() { dialog.value?.close(); }
function csv(value) { return String(value ?? '').split(',').map((item) => item.trim()).filter(Boolean); }
async function saveEditor() { errorMessage.value = ''; try { let result; const value = editor.values;
  if (editor.kind === 'policy') result = await apiClient.saveIdentityPolicy({ defaultRoleKey: value.defaultRoleKey, expectedVersion: value.expectedVersion, jitEnabled: value.jitEnabled, loginEnforcement: value.loginEnforcement, provider: { audience: value.audience, clientId: value.clientId, decryptionKeyReference: value.decryptionKeyReference, emailAttribute: value.emailAttribute, entryPoint: value.entryPoint, groupsAttribute: value.groupsAttribute, idpCertificate: value.idpCertificate, issuer: value.issuer, metadataUrl: value.metadataUrl, secretReference: value.secretReference, spSigningCertReference: value.spSigningCertReference, spSigningKeyReference: value.spSigningKeyReference }, ssoMode: value.ssoMode }, token.value);
  if (editor.kind === 'break-glass') result = await apiClient.saveBreakGlassPolicy({ enabled: value.enabled, expectedVersion: value.expectedVersion, maxSessionMinutes: Number(value.maxSessionMinutes), userIds: csv(value.userIdsText) }, token.value);
  if (editor.kind === 'domain') result = await apiClient.createVerifiedDomain(value, token.value);
  if (editor.kind === 'verify-domain') result = await apiClient.verifyIdentityDomain(value.domainId, { expectedVersion: value.expectedVersion, proof: value.proof }, token.value);
  if (editor.kind === 'role') result = await apiClient.createCustomRole({ capabilities: csv(value.capabilitiesText), description: value.description, key: value.key, name: value.name }, token.value);
  if (editor.kind === 'group') result = await apiClient.createIdentityGroup({ description: value.description, externalId: value.externalId, name: value.name, roleKeys: csv(value.roleKeysText) }, token.value);
  if (editor.kind === 'service') result = await apiClient.createServiceAccount({ description: value.description, expiresAt: value.expiresAt ? new Date(value.expiresAt).toISOString() : null, name: value.name, projectIds: csv(value.projectIdsText), scopes: csv(value.scopesText) }, token.value);
  if (editor.kind === 'review') result = await apiClient.createAccessReview({ dueAt: new Date(value.dueAt).toISOString(), name: value.name, reviewerUserId: value.reviewerUserId, scope: value.scope }, token.value);
  if (editor.kind === 'review campaign') result = await apiClient.createAccessReviewCampaign({ durationDays: Number(value.durationDays), enabled: value.enabled, intervalDays: Number(value.intervalDays), name: value.name, nextRunAt: new Date(value.nextRunAt).toISOString(), reviewerUserId: value.reviewerUserId, scope: value.scope }, token.value);
  if (editor.kind === 'impersonation') result = await apiClient.requestImpersonation({ expiresAt: new Date(value.expiresAt).toISOString(), reason: value.reason, targetUserId: value.targetUserId }, token.value);
  oneTimeSecret.value = result?.secret ?? ''; oneTimeDomainProof.value = result?.verification?.token ?? result?.verification?.dnsValue ?? '';
  await load(); if (!oneTimeSecret.value && !oneTimeDomainProof.value) closeEditor();
} catch (error) { errorMessage.value = error.message ?? 'Unable to save identity control.'; } }
async function verifyDomain(item) { oneTimeSecret.value = ''; oneTimeDomainProof.value = ''; editor.kind = 'verify-domain'; editor.values = { domainId: item.id, expectedVersion: item.version, proof: '' }; await nextTick(); dialog.value?.showModal(); }
async function rotateCredential(item) { try { const result = await apiClient.rotateServiceAccountCredential(item.id, { expectedVersion: item.version, expiresAt: item.expiresAt }, token.value); oneTimeSecret.value = result.secret; editor.kind = 'secret'; editor.values = {}; await load(); await nextTick(); dialog.value?.showModal(); } catch (error) { errorMessage.value = error.message; } }
async function decideReview(item, decision) { try { await apiClient.decideAccessReviewItem(item.id, { decision, expectedVersion: item.version, note: decision === 'revoke' ? 'Revoked during access certification.' : 'Certified.' }, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
async function toggleReviewCampaign(item) { try { await apiClient.updateAccessReviewCampaign(item.id, { enabled: !item.enabled, expectedVersion: item.version }, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
async function decideImpersonation(item, decision) { try { await apiClient.decideImpersonation(item.id, { decision, expectedVersion: item.version, note: `${decision} through governed admin review.` }, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
// Starting an impersonation session swaps the signed-in user, so it blocks like sign-in.
async function activateImpersonation(item) { try { const result = await apiClient.blocking.activateImpersonation(item.id, token.value); authSession.beginImpersonation(result); await router.push({ name: 'home' }); } catch (error) { errorMessage.value = error.message; } }
async function endImpersonation(item) { try { await apiClient.endImpersonation(item.id, item.version, token.value); await load(); } catch (error) { errorMessage.value = error.message; } }
function dateTime(value) { return value ? new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'; }
onMounted(load);
</script>

<template>
  <main class="identity-page"><header><div><h1>Enterprise identity</h1><p>Tenant SSO policy, verified domains, least-privilege roles, access certification, service credentials, and governed support access.</p></div><button class="btn btn-sm btn-outline-secondary" type="button" @click="load">Refresh</button></header>
    <div v-if="errorMessage" class="alert alert-danger" role="alert">{{ errorMessage }}</div>
    <nav aria-label="Identity control sections"><button v-for="tab in ['policy','break glass','domains','roles','groups','reviews','service accounts','impersonation']" :key="tab" :class="{ active: activeTab === tab }" type="button" @click="activeTab = tab">{{ tab }}</button></nav>
    <p v-if="loading" role="status">Loading identity controls…</p>
    <template v-else>
      <section v-if="activeTab === 'policy'" aria-labelledby="identity-policy-title"><div class="section-heading"><h2 id="identity-policy-title">Authentication policy</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('policy')">Edit policy</button></div><dl class="summary"><div><dt>SSO mode</dt><dd>{{ workspace.policy?.ssoMode ?? 'none' }}</dd></div><div><dt>Enforcement</dt><dd>{{ workspace.policy?.loginEnforcement ?? 'optional' }}</dd></div><div><dt>Just-in-time provisioning</dt><dd>{{ workspace.policy?.jitEnabled ? 'Enabled' : 'Disabled' }}</dd></div><div><dt>Default role</dt><dd>{{ workspace.policy?.defaultRoleKey ?? 'user' }}</dd></div><div><dt>Provider issuer</dt><dd>{{ workspace.policy?.provider?.issuer || 'Not configured' }}</dd></div></dl></section>
      <section v-if="activeTab === 'break glass'" aria-labelledby="identity-break-glass-title"><div class="section-heading"><h2 id="identity-break-glass-title">Break-glass access</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('break-glass')">Configure</button></div><p>Designated local tenant administrators can bypass an unavailable identity provider only after password and MFA verification. Sessions are access-token only, time bounded, audited, and invalidated whenever this policy changes.</p><dl class="summary"><div><dt>Status</dt><dd>{{ workspace.breakGlassPolicy?.enabled ? 'enabled' : 'disabled' }}</dd></div><div><dt>Maximum session</dt><dd>{{ workspace.breakGlassPolicy?.maxSessionMinutes ?? 15 }} minutes</dd></div><div><dt>Designated users</dt><dd>{{ workspace.breakGlassPolicy?.userIds?.join(', ') || 'None' }}</dd></div><div><dt>Version</dt><dd>{{ workspace.breakGlassPolicy?.version ?? 0 }}</dd></div></dl></section>
      <section v-if="activeTab === 'domains'" aria-labelledby="identity-domains-title"><div class="section-heading"><h2 id="identity-domains-title">Verified domains</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('domain')">Add domain</button></div><div class="table-responsive"><table><thead><tr><th>Domain</th><th>Method</th><th>Status</th><th>Verified</th><th>Action</th></tr></thead><tbody><tr v-for="item in workspace.domains" :key="item.id"><td>{{ item.domain }}</td><td>{{ item.verificationMethod }}</td><td><span class="status">{{ item.status }}</span></td><td>{{ dateTime(item.verifiedAt) }}</td><td><button v-if="item.status !== 'verified'" class="btn btn-sm btn-outline-secondary" type="button" @click="verifyDomain(item)">Verify</button></td></tr></tbody></table></div><p v-if="!workspace.domains.length" class="empty">No domains configured.</p></section>
      <section v-if="activeTab === 'roles'" aria-labelledby="identity-roles-title"><div class="section-heading"><h2 id="identity-roles-title">Custom roles</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('role')">Add role</button></div><div class="table-responsive"><table><thead><tr><th>Role</th><th>Key</th><th>Capabilities</th><th>Version</th></tr></thead><tbody><tr v-for="item in workspace.roles" :key="item.id"><td>{{ item.name }}</td><td><code>{{ item.key }}</code></td><td>{{ item.capabilities.join(', ') }}</td><td>{{ item.version }}</td></tr></tbody></table></div><p v-if="!workspace.roles.length" class="empty">No custom roles.</p></section>
      <section v-if="activeTab === 'groups'" aria-labelledby="identity-groups-title"><div class="section-heading"><h2 id="identity-groups-title">Groups & mappings</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('group')">Add group</button></div><div class="table-responsive"><table><thead><tr><th>Group</th><th>External ID</th><th>Roles</th><th>Members</th></tr></thead><tbody><tr v-for="item in workspace.groups" :key="item.id"><td>{{ item.name }}</td><td>{{ item.externalId || '—' }}</td><td>{{ item.roleKeys.join(', ') }}</td><td>{{ workspace.groupMemberships.filter((record) => record.groupId === item.id).length }}</td></tr></tbody></table></div><p v-if="!workspace.groups.length" class="empty">No groups configured.</p></section>
      <section v-if="activeTab === 'reviews'" aria-labelledby="identity-reviews-title">
        <div class="section-heading"><div><h2 id="identity-reviews-title">Access certification</h2><p>Run one-time reviews or schedule recurring, idempotent certification campaigns.</p></div><div class="actions"><button class="btn btn-sm btn-outline-secondary" type="button" @click="openEditor('review')">Start review</button><button class="btn btn-sm btn-primary" type="button" @click="openEditor('review campaign')">Schedule campaign</button></div></div>
        <h3>Campaigns</h3><div class="table-responsive" tabindex="0" aria-label="Scheduled access review campaigns"><table><thead><tr><th>Campaign</th><th>Scope</th><th>Reviewer</th><th>Cadence</th><th>Next run</th><th>Runs</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="item in workspace.accessReviewCampaigns" :key="item.id"><td>{{ item.name }}</td><td>{{ item.scope }}</td><td>{{ item.reviewerUserId }}</td><td>Every {{ item.intervalDays }} days · {{ item.durationDays }} day window</td><td>{{ dateTime(item.nextRunAt) }}</td><td>{{ item.runCount }}</td><td>{{ item.enabled ? 'Enabled' : 'Paused' }}</td><td><button class="btn btn-sm btn-outline-secondary" type="button" @click="toggleReviewCampaign(item)">{{ item.enabled ? 'Pause' : 'Resume' }}</button></td></tr></tbody></table></div><p v-if="!workspace.accessReviewCampaigns.length" class="empty">No scheduled certification campaigns.</p>
        <h3>Review items</h3><div class="table-responsive" tabindex="0" aria-label="Access review items"><table><thead><tr><th>Subject</th><th>Access</th><th>Decision</th><th>Action</th></tr></thead><tbody><tr v-for="item in workspace.accessReviewItems" :key="item.id"><td>{{ item.subjectType }} · {{ item.subjectId }}</td><td>{{ item.subjectType === 'user' ? groupMap.get(item.access.groupId)?.name : accountMap.get(item.subjectId)?.name }}</td><td>{{ item.decision }}</td><td><div v-if="item.decision === 'pending'" class="actions"><button class="btn btn-sm btn-outline-secondary" type="button" @click="decideReview(item,'approve')">Certify</button><button class="btn btn-sm btn-outline-danger" type="button" @click="decideReview(item,'revoke')">Revoke</button></div></td></tr></tbody></table></div><p v-if="!workspace.accessReviewItems.length" class="empty">No access review items.</p>
      </section>
      <section v-if="activeTab === 'service accounts'" aria-labelledby="identity-service-title"><div class="section-heading"><h2 id="identity-service-title">Service accounts</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('service')">Add service account</button></div><div class="table-responsive"><table><thead><tr><th>Name</th><th>Scopes</th><th>Projects</th><th>Status</th><th>Expires</th><th>Credentials</th><th>Action</th></tr></thead><tbody><tr v-for="item in workspace.serviceAccounts" :key="item.id"><td>{{ item.name }}</td><td>{{ item.scopes.join(', ') }}</td><td>{{ item.projectIds?.join(', ') || 'None' }}</td><td>{{ item.enabled ? 'Enabled' : 'Disabled' }}</td><td>{{ dateTime(item.expiresAt) }}</td><td>{{ workspace.credentials.filter((record) => record.accountId === item.id && !record.revokedAt).map((record) => record.prefix).join(', ') || 'None' }}</td><td><button class="btn btn-sm btn-outline-secondary" type="button" @click="rotateCredential(item)">Rotate</button></td></tr></tbody></table></div><p v-if="!workspace.serviceAccounts.length" class="empty">No service accounts.</p></section>
      <section v-if="activeTab === 'impersonation'" aria-labelledby="identity-impersonation-title"><div class="section-heading"><h2 id="identity-impersonation-title">Governed impersonation</h2><button class="btn btn-sm btn-primary" type="button" @click="openEditor('impersonation')">Request access</button></div><div class="table-responsive"><table><thead><tr><th>Requester</th><th>Target</th><th>Reason</th><th>Expires</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="item in workspace.impersonationGrants" :key="item.id"><td>{{ item.requesterUserId }}</td><td>{{ item.targetUserId }}</td><td>{{ item.reason }}</td><td>{{ dateTime(item.expiresAt) }}</td><td>{{ item.status }}</td><td><div class="actions"><template v-if="item.status === 'pending' && item.requesterUserId !== authSession.state.currentUser?.id"><button class="btn btn-sm btn-outline-secondary" type="button" @click="decideImpersonation(item,'approved')">Approve</button><button class="btn btn-sm btn-outline-danger" type="button" @click="decideImpersonation(item,'rejected')">Reject</button></template><button v-if="item.status === 'approved' && item.requesterUserId === authSession.state.currentUser?.id" class="btn btn-sm btn-primary" type="button" @click="activateImpersonation(item)">Start session</button><button v-if="item.status === 'active' && [item.requesterUserId,item.approvedBy].includes(authSession.state.currentUser?.id)" class="btn btn-sm btn-outline-danger" type="button" @click="endImpersonation(item)">End session</button></div></td></tr></tbody></table></div><p v-if="!workspace.impersonationGrants.length" class="empty">No impersonation requests.</p></section>
    </template>

    <dialog ref="dialog" aria-labelledby="identity-editor-title" @cancel.prevent="closeEditor"><form @submit.prevent="saveEditor"><header><h2 id="identity-editor-title">{{ editor.kind === 'secret' ? 'Copy credential now' : `Configure ${editor.kind}` }}</h2><button class="icon-button" aria-label="Close identity editor" type="button" @click="closeEditor"><i class="bi bi-x-lg"></i></button></header>
      <template v-if="oneTimeSecret"><div class="secret"><strong>Shown once</strong><code>{{ oneTimeSecret }}</code><p>Store this credential in an approved secrets manager. It cannot be retrieved again.</p></div></template>
      <template v-else-if="oneTimeDomainProof"><div class="secret"><strong>Verification value</strong><code>{{ oneTimeDomainProof }}</code><p>Use this value for the configured manual or DNS verification method.</p></div></template>
      <template v-else-if="editor.kind === 'policy'"><div class="form-grid"><label>SSO mode<select v-model="editor.values.ssoMode"><option value="none">none</option><option value="oidc">OIDC</option><option value="saml">SAML 2.0</option></select></label><label>Enforcement<select v-model="editor.values.loginEnforcement"><option value="optional">optional</option><option value="required">required</option></select></label><label>Default role<input v-model="editor.values.defaultRoleKey" required /></label><label class="check"><input v-model="editor.values.jitEnabled" type="checkbox" /> Enable JIT</label><label>Identity-provider issuer<input v-model="editor.values.issuer" :required="editor.values.ssoMode !== 'none'" /></label><template v-if="editor.values.ssoMode === 'oidc'"><label>Metadata URL<input v-model="editor.values.metadataUrl" type="url" /></label><label>Client ID<input v-model="editor.values.clientId" required /></label><label>Client secret reference<input v-model="editor.values.secretReference" placeholder="env:TENANT_OIDC_CLIENT_SECRET" /></label></template><template v-if="editor.values.ssoMode === 'saml'"><label>Identity-provider SSO URL<input v-model="editor.values.entryPoint" type="url" required /></label><label>Service-provider entity ID <small>Defaults to the tenant metadata URL</small><input v-model="editor.values.audience" /></label><label class="wide">Identity-provider signing certificate<textarea v-model="editor.values.idpCertificate" required spellcheck="false"></textarea></label><label>Email attribute<input v-model="editor.values.emailAttribute" required /></label><label>Groups attribute<input v-model="editor.values.groupsAttribute" required /></label><label>SP signing key reference<input v-model="editor.values.spSigningKeyReference" placeholder="env:TENANT_SAML_SIGNING_KEY" /></label><label>SP signing certificate reference<input v-model="editor.values.spSigningCertReference" placeholder="env:TENANT_SAML_SIGNING_CERT" /></label><label>Assertion decryption key reference<input v-model="editor.values.decryptionKeyReference" placeholder="env:TENANT_SAML_DECRYPTION_KEY" /></label></template></div></template>
      <template v-else-if="editor.kind === 'break-glass'"><label class="check"><input v-model="editor.values.enabled" type="checkbox" /> Enable emergency access</label><label>Designated user IDs <small>Comma separated local tenant administrators with MFA</small><textarea v-model="editor.values.userIdsText" :required="editor.values.enabled"></textarea></label><label>Maximum session minutes<input v-model.number="editor.values.maxSessionMinutes" type="number" min="5" max="60" required /></label></template>
      <template v-else-if="editor.kind === 'domain'"><label>Domain<input v-model="editor.values.domain" required /></label><label>Verification method<select v-model="editor.values.verificationMethod"><option value="manual">manual</option><option value="dns_txt">DNS TXT</option></select></label></template>
      <template v-else-if="editor.kind === 'verify-domain'"><label>Verification value<input v-model="editor.values.proof" required autocomplete="off" /></label></template>
      <template v-else-if="editor.kind === 'role'"><label>Name<input v-model="editor.values.name" required /></label><label>Key<input v-model="editor.values.key" required pattern="[a-z][a-z0-9_]+" /></label><label>Description<textarea v-model="editor.values.description"></textarea></label><label>Capabilities <small>Comma separated</small><textarea v-model="editor.values.capabilitiesText" required></textarea></label></template>
      <template v-else-if="editor.kind === 'group'"><label>Name<input v-model="editor.values.name" required /></label><label>External ID<input v-model="editor.values.externalId" /></label><label>Description<textarea v-model="editor.values.description"></textarea></label><label>Role keys <small>Comma separated</small><input v-model="editor.values.roleKeysText" required /></label></template>
      <template v-else-if="editor.kind === 'service'"><label>Name<input v-model="editor.values.name" required /></label><label>Description<textarea v-model="editor.values.description"></textarea></label><label>Scopes <small>Comma separated</small><textarea v-model="editor.values.scopesText" required></textarea></label><label>Project IDs <small>Comma separated</small><textarea v-model="editor.values.projectIdsText" required></textarea></label><label>Expires<input v-model="editor.values.expiresAt" type="datetime-local" /></label></template>
      <template v-else-if="editor.kind === 'review'"><label>Name<input v-model="editor.values.name" required /></label><label>Reviewer user ID<input v-model="editor.values.reviewerUserId" required /></label><label>Scope<select v-model="editor.values.scope"><option value="tenant">tenant</option><option value="groups">groups</option><option value="service_accounts">service accounts</option></select></label><label>Due<input v-model="editor.values.dueAt" type="datetime-local" required /></label></template>
      <template v-else-if="editor.kind === 'review campaign'"><label>Name<input v-model="editor.values.name" required /></label><label>Reviewer administrator ID<input v-model="editor.values.reviewerUserId" required /></label><label>Scope<select v-model="editor.values.scope"><option value="tenant">tenant</option><option value="groups">groups</option><option value="service_accounts">service accounts</option></select></label><label>First run<input v-model="editor.values.nextRunAt" type="datetime-local" required /></label><label>Repeat every days<input v-model.number="editor.values.intervalDays" type="number" min="7" max="366" required /></label><label>Review window days<input v-model.number="editor.values.durationDays" type="number" min="1" max="90" required /></label><label class="check"><input v-model="editor.values.enabled" type="checkbox" /> Enable campaign</label></template>
      <template v-else-if="editor.kind === 'impersonation'"><label>Target user ID<input v-model="editor.values.targetUserId" required /></label><label>Reason<textarea v-model="editor.values.reason" minlength="10" required></textarea></label><label>Expires<input v-model="editor.values.expiresAt" type="datetime-local" required /></label></template>
      <footer><button class="btn btn-sm btn-outline-secondary" type="button" @click="closeEditor">Close</button><button v-if="!oneTimeSecret && !oneTimeDomainProof && editor.kind !== 'secret'" class="btn btn-sm btn-primary" type="submit">Save</button></footer>
    </form></dialog>
  </main>
</template>

<style scoped>
